//! Vendored schema bundle embedded at compile time (FR-069 Inputs).
//!
//! `module-manifest.schema.json` and `PROVENANCE.json` are GENERATED by
//! scripts/vendor-semantic-schemas.sh from schemas/vendored/; do not edit
//! those by hand. `COMMON_SCHEMA` and the semantic-core 0.2.0 bundle are
//! resolved through the `filament-core-data` dependency instead (PLAT-906) —
//! `build.rs` copies them into `OUT_DIR` at build time; nothing under
//! `schemas/vendored/` backs them. Embedding (rather than reading the
//! filesystem at runtime) is what lets the resolver run unchanged under the
//! `wasm` feature either way (FR-069-AC-5).
//!
//! There is no semantic-core 0.1.0 bundle (PLAT-906): no commit of
//! `filament-core-data` carries both a Cargo package and 0.1.0-vintage schema
//! bytes (its workspace was added in the same commit that bumped
//! semantic-core to 0.2.0), so 0.1.0 has no dependency edge to resolve
//! through, and quire-rs no longer carries a committed copy of it either.
//! `semantic_core_bundle("0.1.0")` returns `None`; a module declaring
//! `semantic_core: 0.1.0` fails to load until `filament-core-data` publishes
//! 0.1.0 in a resolvable form (see the PLAT-906 PR description).

/// The `semantic.contract_version` this engine understands.
pub const CONTRACT_VERSION: &str = "1.0.0";
/// Base of every semantic-core `$id`.
pub const SEMANTIC_CORE_BASE: &str = "https://schemas.agent-ix.org/semantic-core/";
/// Base of every module-emitted `$id`.
pub const MODULE_SCHEMA_BASE: &str = "https://schemas.agent-ix.org/";

pub const MODULE_MANIFEST_SCHEMA: &str =
    include_str!("../../schemas/vendored/module-manifest.schema.json");
/// filament-core-data's `schema/semantic/v1/common.schema.json`, copied into
/// `OUT_DIR` by `build.rs` from the pinned dependency checkout.
pub const COMMON_SCHEMA: &str = include_str!(concat!(env!("OUT_DIR"), "/common.schema.json"));
pub const PROVENANCE: &str = include_str!("../../schemas/vendored/PROVENANCE.json");

/// Semantic-core versions with an embedded bundle, ascending. There is no
/// 0.1.0 entry — see the module doc comment.
pub const SEMANTIC_CORE_VERSIONS: &[&str] = &["0.2.0"];

