/// The embedded bundle for `version`, if any. `"0.1.0"` falls through to
/// `None` like any other unrecognized version — see the module doc comment.
pub fn semantic_core_bundle(version: &str) -> Option<&'static [(&'static str, &'static str)]> {
    match version {
        "0.2.0" => Some(SEMANTIC_CORE_0_2_0),
        _ => None,
    }
}
